                dockGroupNodeId : sortConfig.dockGroupNodeId,
                dockItemIds     : [...plan.desiredItems],
                dockSourceNodeId: sortConfig.dockSourceNodeId,
                dockWorkspaceId : sortConfig.dockWorkspaceId,
                sortGroup       : sortConfig.sortGroup
